MS.hook('resource:keep', function (kind, url) {
  if (kind !== 'video') return true;
  var exts = MS.config.get('exts', ['.mp4', '.webm', '.mkv', '.mov', '.m4v', '.flv']);
  var u = String(url || '').toLowerCase().split('#')[0].split('?')[0];
  for (var i = 0; i < exts.length; i++) {
    var e = String(exts[i] || '').toLowerCase();
    if (e && u.slice(-e.length) === e) return true;
  }
  return false;
});

var seen = Object.create(null);
MS.hook('resource:keep', function (kind, url) {
  var u = String(url || '');
  if (!u) return true;
  var key;
  try {
    var a = new URL(u, location.href);
    key = a.origin + a.pathname;
  } catch (e) {
    key = u.split('#')[0].split('?')[0];
  }
  if (seen[key]) return false;
  seen[key] = 1;
  return true;
});

MS.hook('resource:keep', function (kind, url, meta) {
  if (kind !== 'img') return true;
  var junk = /(pixel|spacer|blank|transparent|1x1|loading|placeholder|clear\.gif|spacer\.gif)/i;
  if (junk.test(String(url || ''))) return false;
  var minBytes = MS.config.get('minBytes', 8192);
  var minW = MS.config.get('minWidth', 100);
  var minH = MS.config.get('minHeight', 100);
  if (meta) {
    if (meta.size > 0 && minBytes > 0 && meta.size < minBytes) return false;
    if (meta.width > 0 && minW > 0 && meta.width < minW) return false;
    if (meta.height > 0 && minH > 0 && meta.height < minH) return false;
  }
  return true;
});

MS.hook('resource:keep', function (kind, url) {
  var hosts = MS.config.get('hosts', []);
  if (!hosts || !hosts.length) return true;
  var h = '';
  try {
    h = new URL(String(url), location.href).hostname.toLowerCase();
  } catch (e) {
    return true;
  }
  for (var i = 0; i < hosts.length; i++) {
    var d = String(hosts[i] || '').toLowerCase().trim().replace(/^\.+/, '');
    if (!d) continue;
    if (h === d) return false;
    if (h.length > d.length && h.slice(-(d.length + 1)) === '.' + d) return false;
  }
  return true;
});

MS.hook('download:filename', function (name, url, idx) {
  var sep = MS.config.get('sep', '_');
  var host = '';
  try {
    host = new URL(String(url), location.href).hostname.replace(/^www\./, '');
  } catch (e) {
    return name;
  }
  if (!host) return name;
  if (String(name).indexOf(host + sep) === 0) return name;
  return host + sep + name;
});

MS.hook('download:filename', function (name, url, idx) {
  var pad = MS.config.get('pad', 3);
  var sep = MS.config.get('sep', '_');
  var n = String(idx || 0);
  while (n.length < pad) n = '0' + n;
  if (String(name).indexOf(n + sep) === 0) return name;
  return n + sep + name;
});

MS.hook('download:quality', function (pref) {
  var q = MS.config.get('quality', 'high');
  if (q === 'high' || q === 'medium' || q === 'low') return q;
  return pref;
});

MS.hook('render:layout', function (cur, kind) {
  var w = MS.config.get('minCardWidth', 96);
  w = parseInt(w, 10);
  if (!w || w < 60 || w > 320) return cur;
  return { minCardWidth: w };
});

MS.hook('render:footerButtons', function (kind, list) {
  return [{
    label: '复制文件名',
    icon: '📋',
    onClick: function () {
      var arr = MS.media.list(kind) || [];
      if (!arr.length) { MS.toast('当前列表为空', 'warn'); return; }
      var names = [];
      for (var i = 0; i < arr.length; i++) {
        var u = String(arr[i]).split('#')[0].split('?')[0];
        var n = u.split('/').pop();
        names.push(n || u);
      }
      var text = names.join('\n');
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text);
        }
      } catch (e) {}
      MS.log(text);
      MS.toast('已复制 ' + names.length + ' 个文件名', 'success');
    }
  }];
});

MS.hook('theme:colors', function (colors) {
  try {
    var c = colors || {};
    return {
      bg: '#05070d',
      bg2: '#0b1220',
      bg3: '#141c2b',
      txt: '#e8eefc',
      sub: '#93a4c0',
      border: '#1f2a3d',
      primary: c.primary,
      primary2: c.primary2,
      success: c.success,
      warn: c.warn,
      danger: c.danger
    };
  } catch (e) {
    return colors;
  }
});

MS.hook('shortcuts', function () {
  var mod = MS.config.get('mod', 'alt');
  var key = MS.config.get('key', 'e');
  return [{
    mod: mod,
    key: key,
    run: function () {
      var arr = MS.media.list('img').concat(MS.media.list('video') || []);
      if (!arr.length) { MS.toast('还没有资源', 'warn'); return; }
      var text = arr.join('\n');
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text);
        }
      } catch (e) {}
      MS.log(text);
      MS.toast('已复制 ' + arr.length + ' 条链接', 'success');
    }
  }];
});

MS.hook('parse:result', function (result) {
  if (!result) return result;
  var pat = MS.config.get('pattern', 'watermark|logo|_wm|wm_|/wm/');
  if (!pat) return result;
  var re;
  try {
    re = new RegExp(pat, 'i');
  } catch (e) {
    return result;
  }
  try {
    if (result.videoUrls && result.videoUrls.length > 1) {
      var clean = [];
      for (var i = 0; i < result.videoUrls.length; i++) {
        if (!re.test(String(result.videoUrls[i]))) clean.push(result.videoUrls[i]);
      }
      if (clean.length && clean.length < result.videoUrls.length) {
        result.videoUrls = clean;
        result.videoUrl = clean[0];
      }
    }
  } catch (e2) {}
  return result;
});
